-- V5_3（H2）ログインに必要なデータだけになった M_APPLICANT を申込者アカウント（M_APPLICANT_ACCOUNT）に改名し、申込からの外部キーを張り直す
ALTER TABLE M_APPLICANT RENAME TO M_APPLICANT_ACCOUNT;
ALTER TABLE M_APPLICANT_ACCOUNT RENAME CONSTRAINT PK_M_APPLICANT TO PK_M_APPLICANT_ACCOUNT;
ALTER TABLE M_APPLICANT_ACCOUNT RENAME CONSTRAINT UK_M_APPLICANT_01 TO UK_M_APPLICANT_ACCOUNT_01;
ALTER TABLE T_APPLICATION ADD CONSTRAINT FK_T_APPLICATION_APPLICANT FOREIGN KEY (APPLICANT_ID) REFERENCES M_APPLICANT_ACCOUNT (APPLICANT_ID);
